// Frontend/src/hooks/useMessages.js
import { useState, useEffect, useCallback } from 'react';

const API_URL = 'http://localhost:5000/api';

const useMessages = () => {
  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [currentConversation, setCurrentConversation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Fonction pour obtenir le token d'authentification
  // Frontend/src/hooks/useMessages.js - Fonction getToken corrigée
  const getToken = () => {
    try {
      const userData = localStorage.getItem('userData');
      if (!userData) return null;

      const parsedData = JSON.parse(userData);
      console.log('User data complet:', parsedData);

      // Essayer plusieurs noms possibles pour le token
      return parsedData.token ||
        parsedData.access_token ||
        parsedData.accessToken ||
        null;
    } catch (err) {
      console.error('Erreur lors de la récupération du token:', err);
      return null;
    }
  };

  // Fonction pour obtenir les headers
  const getHeaders = () => {
    const token = getAuthToken();
    console.log('Token récupéré:', token ? 'Oui' : 'Non');

    const headers = {
      'Content-Type': 'application/json',
    };

    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    return headers;
  };

  // Fonction pour vérifier l'authentification
  const checkAuth = () => {
    const token = getAuthToken();
    if (!token) {
      setError('Vous n\'êtes pas connecté. Veuillez vous connecter.');
      return false;
    }
    return true;
  };

  // Récupérer toutes les conversations
  const fetchConversations = useCallback(async () => {
    try {
      if (!checkAuth()) return;

      setLoading(true);
      setError(null);

      console.log('Fetching conversations...');
      const response = await fetch(`${API_URL}/messages/conversations`, {
        headers: getHeaders()
      });

      console.log('Response status:', response.status);

      if (response.status === 401) {
        setError('Session expirée. Veuillez vous reconnecter.');
        localStorage.removeItem('userData');
        return;
      }

      if (!response.ok) {
        throw new Error(`Erreur HTTP: ${response.status}`);
      }

      const data = await response.json();
      console.log('Conversations data:', data);

      if (data.success) {
        setConversations(data.conversations || []);
      } else {
        setError(data.message || 'Erreur lors du chargement des conversations');
      }
    } catch (err) {
      console.error('Erreur fetchConversations:', err);
      setError('Impossible de charger les conversations. Veuillez réessayer.');
    } finally {
      setLoading(false);
    }
  }, []);

  // Récupérer les messages d'une conversation
  const fetchMessages = useCallback(async (conversationId) => {
    try {
      if (!checkAuth()) return;

      setLoading(true);
      setError(null);

      console.log(`Fetching messages for conversation ${conversationId}...`);
      const response = await fetch(`${API_URL}/messages/conversations/${conversationId}/messages`, {
        headers: getHeaders()
      });

      console.log('Messages response status:', response.status);

      if (response.status === 401) {
        setError('Session expirée. Veuillez vous reconnecter.');
        localStorage.removeItem('userData');
        return;
      }

      if (!response.ok) {
        throw new Error(`Erreur HTTP: ${response.status}`);
      }

      const data = await response.json();
      console.log('Messages data:', data);

      if (data.success) {
        setMessages(data.messages || []);

        // Mettre à jour la conversation courante
        if (data.conversation) {
          setCurrentConversation(data.conversation);
        } else {
          // Chercher dans les conversations existantes
          const conv = conversations.find(c => c.id === conversationId);
          if (conv) {
            setCurrentConversation(conv);
          }
        }
      } else {
        setError(data.message || 'Erreur lors du chargement des messages');
      }
    } catch (err) {
      console.error('Erreur fetchMessages:', err);
      setError('Impossible de charger les messages. Veuillez réessayer.');
    } finally {
      setLoading(false);
    }
  }, [conversations]);

  // Envoyer un message
  const sendMessage = useCallback(async (conversationId, content) => {
    try {
      if (!checkAuth()) return;

      console.log('Sending message...', { conversationId, content });
      const response = await fetch(`${API_URL}/messages`, {
        method: 'POST',
        headers: getHeaders(),
        body: JSON.stringify({ conversationId, content })
      });

      console.log('Send message response status:', response.status);

      if (response.status === 401) {
        setError('Session expirée. Veuillez vous reconnecter.');
        localStorage.removeItem('userData');
        return null;
      }

      if (!response.ok) {
        throw new Error(`Erreur HTTP: ${response.status}`);
      }

      const data = await response.json();
      console.log('Send message response:', data);

      if (data.success) {
        // Ajouter le nouveau message à la liste
        setMessages(prev => [...prev, data.message]);

        // Mettre à jour la dernière conversation
        setConversations(prev =>
          prev.map(conv =>
            conv.id === conversationId
              ? {
                ...conv,
                last_message: content,
                last_message_time: new Date().toISOString(),
                unread_count: 0
              }
              : conv
          )
        );

        return data.message;
      } else {
        setError(data.message || 'Erreur lors de l\'envoi du message');
        return null;
      }
    } catch (err) {
      console.error('Erreur sendMessage:', err);
      setError('Impossible d\'envoyer le message. Veuillez réessayer.');
      return null;
    }
  }, []);

  // Initialiser au montage
  useEffect(() => {
    fetchConversations();
  }, [fetchConversations]);

  return {
    conversations,
    messages,
    currentConversation,
    loading,
    error,
    fetchConversations,
    fetchMessages,
    sendMessage,
    setError
  };
};

export default useMessages;
